(* [comment removed for export] *)
Lemma lin_align_sound : forall segs E M kn ts,
  know_ok segs E M kn ->
  (0 <= lin_align (ealign kn) ts <= 12)%Z /\ (2 ^ lin_align (ealign kn) ts | tden E ts)%Z.
Proof.
