#[using="Type"] Lemma log_byte_lit_sound : forall E base log rb rk b,
  log_flat E log ->
  log_byte_lit log rb rk = Some b ->
  flat E (SA rb rk) 1 ->
  rdn segs (mem_denot E base log) (adenot E (SA rb rk)) 1 = Some [Z_to_bv 8 b] /\ (0 <= b < 256)%Z.
Proof.
